def location(rel):
 p=R/rel
 if not p.exists():return '`'+rel+'`（路径待更正）'
 syms=[]
 if p.suffix=='.py':
  try:
   for n in ast.parse(p.read_text()).body:
    if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)):syms.append((n.name,n.lineno))
  except SyntaxError:pass
 if p.name.startswith('test_'):
  syms=[x for x in syms if x[0].startswith('test_') or x[0].startswith('Test')]
 if rel in PREFERRED:
  syms=[x for name in PREFERRED[rel] for x in syms if x[0]==name]
 line=syms[0][1] if syms else 1
 names=', '.join(x[0] for x in syms[:10])
 return f'[{rel}]({p}:{line})'+(' — `'+names+'`' if names else '')
